UPDATE cohort_summary
SET example_comment =
    (SELECT contact_notes FROM participants p WHERE p.cohort = cohort_summary.cohort LIMIT 1);

UPDATE cohort_summary
SET example_comment = ('Prefers evening sessions; no additional contact info recorded')
WHERE cohort = 'A';

UPDATE cohort_summary
SET example_comment = ('Attended baseline; prefers weekend appointments')
WHERE cohort = 'B';
